/*
 * Parse configuration and prepare domains for lookup
 */

const domainsString = $json.target_domains || '';
const domains = domainsString.split(',').map(d => d.trim()).filter(d => d);
const targetTech = ($json.target_technologies || '').split(',').map(t => t.trim().toLowerCase());

return domains.map(domain => ({
  domain: domain,
  target_technologies: targetTech,
  target_tech_string: $json.target_technologies,
  decision_maker_title: $json.decision_maker_title,
  reason_template: $json.reason_to_reach_out
}));

/*
 * Analyze tech stack for target technology matches
 * Flags companies using any of the target technologies
 */

const techData = $json.data || [];
const inputData = $input.first().json;
const targetTech = inputData.target_technologies || [];

// Extract all technology names (lowercase for matching)
const techNames = techData.map(t => (t.name || '').toLowerCase());

// Find matching technologies
const matchedTech = targetTech.filter(target => 
  techNames.some(tech => tech.includes(target) || target.includes(tech))
);

// Categorize the full tech stack
const categorized = {};
techData.forEach(tech => {
  const cats = tech.categories || ['Other'];
  cats.forEach(cat => {
    if (!categorized[cat]) categorized[cat] = [];
    categorized[cat].push(tech.name);
  });
});

return {
  domain: inputData.domain,
  tech_match: {
    has_target_tech: matchedTech.length > 0,
    matched_technologies: matchedTech,
    match_count: matchedTech.length,
    total_target_tech: targetTech.length
  },
  tech_stack: {
    total_count: techData.length,
    technologies: techData.map(t => t.name).slice(0, 30),
    categories: categorized
  },
  decision_maker_title: inputData.decision_maker_title,
  reason_template: inputData.reason_template,
  target_tech_string: inputData.target_tech_string
};

/*
 * Build qualified lead record with tech-based personalization
 */

const techAnalysis = $('📊 Analyze Tech Stack').item.json;
const companyData = $('🏢 Get Company Info').first().json || {};
const contactData = $('👤 Find Decision Maker').first().json || {};
const emailData = $('📧 Find Email').first().json || {};

// Generate personalized outreach reason
const matchedTechStr = techAnalysis.tech_match.matched_technologies.join(', ');
const reason = techAnalysis.reason_template.replace('{tech}', matchedTechStr);

const priority = techAnalysis.tech_match.match_count >= 2 ? 'HIGH' : 'MEDIUM';

return {
  lead_type: 'TECH_STACK_MATCH',
  priority: priority,
  company: {
    name: companyData.name || companyData.company_name,
    domain: techAnalysis.domain,
    industry: companyData.industry,
    employees: companyData.employeesCount,
    location: companyData.hq || companyData.location,
    description: companyData.shortDescription
  },
  tech_intel: {
    matched_technologies: techAnalysis.tech_match.matched_technologies,
    match_count: techAnalysis.tech_match.match_count,
    full_stack: techAnalysis.tech_stack.technologies,
    tech_categories: Object.keys(techAnalysis.tech_stack.categories),
    total_technologies: techAnalysis.tech_stack.total_count
  },
  contact: {
    name: contactData.full_name || `${contactData.first_name || ''} ${contactData.last_name || ''}`.trim(),
    title: contactData.job_title || contactData.title,
    email: emailData.email,
    email_verified: emailData.deliverable,
    linkedin_url: contactData.profile_url || contactData.linkedin_url
  },
  outreach: {
    personalized_reason: reason,
    talking_points: [
      `✅ Currently using ${matchedTechStr}`,
      `💻 Tech-savvy company with ${techAnalysis.tech_stack.total_count} tools in their stack`,
      companyData.industry ? `🏢 ${companyData.industry} industry` : null
    ].filter(p => p)
  },
  meta: {
    created_at: new Date().toISOString(),
    credits_used: null
  }
};
